// This file was generated by Prisma, and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts"
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});
import "dotenv/config";
import { PrismaClient, StatusCategory } from "../src/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import * as bcrypt from "bcryptjs";

const adapter = new PrismaPg({ connectionString: process.env.DATABASE_URL });
const prisma = new PrismaClient({ adapter });

async function main() {
  const user = await prisma.user.upsert({
    where: { email: 'tu@taskflow.dev' },
    update: {},
    create: {
      email: 'tu@taskflow.dev',
      // Tài khoản demo CHỈ dùng ở local — đổi mật khẩu trước khi deploy
      passwordHash: await bcrypt.hash('Taskflow123', 10),
      name: 'Tú',
      timezone: 'Asia/Ho_Chi_Minh',
    },
  });

  const workspace = await prisma.workspace.upsert({
    where: { slug: 'taskflow-demo' },
    update: {},
    create: {
      name: 'TaskFlow Demo',
      slug: 'taskflow-demo',
      ownerId: user.id,
    },
  });

  await prisma.workspaceMember.upsert({
    where: { workspaceId_userId: { workspaceId: workspace.id, userId: user.id } },
    update: { role: 'OWNER' },
    create: { workspaceId: workspace.id, userId: user.id, role: 'OWNER' },
  });

  const project = await prisma.project.upsert({
    where: { workspaceId_key: { workspaceId: workspace.id, key: 'TF' } },
    update: {},
    create: {
      workspaceId: workspace.id,
      key: 'TF',
      name: 'TaskFlow Demo',
      description: 'Project mẫu để test issue, board và sprint',
      leadId: user.id,
      issueCounter: 2,
    },
  });

  const statuses = [
    { name: 'To Do', category: StatusCategory.TODO, position: 0 },
    { name: 'In Progress', category: StatusCategory.DOING, position: 1 },
    { name: 'In Review', category: StatusCategory.DOING, position: 2 },
    { name: 'Blocked', category: StatusCategory.DOING, position: 3 },
    { name: 'Done', category: StatusCategory.DONE, position: 4 },
  ];
  const statusRows = [];
  for (const s of statuses) {
    statusRows.push(
      await prisma.status.upsert({
        where: { projectId_name: { projectId: project.id, name: s.name } },
        update: { category: s.category, position: s.position },
        create: { projectId: project.id, ...s },
      }),
    );
  }
  // Status đã có @@unique([projectId, name]) trong schema nên upsert chạy được.

  const todo = statusRows[0];
  await prisma.issue.upsert({
    where: { projectId_number: { projectId: project.id, number: 1 } },
    update: {},
    create: {
      projectId: project.id,
      number: 1,
      type: 'STORY',
      title: 'Cài đặt môi trường dev TaskFlow',
      statusId: todo.id,
      priority: 'HIGH',
      reporterId: user.id,
      assigneeId: user.id,
      storyPoint: 3,
      position: 0,
    },
  });
  await prisma.issue.upsert({
    where: { projectId_number: { projectId: project.id, number: 2 } },
    update: {},
    create: {
      projectId: project.id,
      number: 2,
      type: 'TASK',
      title: 'Tạo workspace + project đầu tiên',
      statusId: todo.id,
      priority: 'MEDIUM',
      reporterId: user.id,
      assigneeId: user.id,
      storyPoint: 2,
      position: 1,
    },
  });

  console.log('Seed xong: 1 user, 1 workspace, 1 project TF, 5 status, 2 issue (TF-1, TF-2)');
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(async () => { await prisma.$disconnect(); });